  const common = [['New check', 'root'], ['2 ways to make this surer', 'sheet:N03'], ["I'm not buying it", 'root|toast:Marked as not buying. It moves to Your decisions.~Undo']];
  const ansH = (o = []) => [...o, ...common, ['Buy later', 'sheet:D60H'], ['Cheaper one', 'sheet:D61H'], ['Installments', 'sheet:D42H'], ['Cash and installments side by side', 'go:D62H'], ...detail('H'), ['I bought it', 'sheet:D63H'], ['Save for it', 'go:G04']];
  const ansL = (o = []) => [...o, ...common, ['Cheaper one', 'sheet:D61L'], ['Installments', 'replace:N15'], ['Cash and installments side by side', 'go:N16'], ...detail('L'), ['I bought it', 'sheet:D63L'], ['Save for it', 'go:G04']];
  const ansC = (o = []) => [...o, ...common, ['Cheaper one', 'sheet:D61C'], ['Installments', 'replace:N09'], ['Cash and installments side by side', 'go:D62C'], ...detail('C', { after: 'go:N14', stops: 'go:N17' }), ['I bought it', 'go:N19'], ['Save for it', 'go:N18']];
  const G = 'Decide answers';
  const ans = (id, title, html, wires) => add({ id, title, group: G, html, wires });

