  ans('N02', 'Fits', nb('N02-Fits.dc.html'), ansH([[WHEN(1), 'toast:Bought today it still fits: $3,156 of spare money stays.'], [WHEN(2), 'toast:Bought on Nov 15 it still fits: $3,156 of spare money stays.'], [PAY2, 'sheet:D42H']]));
  // D20: answer from quick estimates (D39)
