  ans('D20', 'Answer from quick estimates', d20, ansH([[WHEN(1), 'toast:Bought today it still fits, by your estimates.'], [WHEN(2), 'toast:Bought on Nov 15 it still fits, by your estimates.'], [PAY2, 'sheet:D42H'], ['2 ways to make this surer', 'go:D31']]));
  ans('N24', 'Not ready yet', nb('N24-NotReady.dc.html'), [['Answer from quick estimates', 'go:D39'], [PAY2, 'sheet:D42H'], [WHEN(1), 'toast:Answers from records start Nov 21.'], [WHEN(2), 'toast:Answers from records start Nov 21.'], ...common]);
