  ans('N12', 'Uses your overdraft', nb('N12-Overdraft.dc.html'), ansL([[WHEN(1), 'toast:Bought today it is Not yet: ready in March 2027.'], [WHEN(2), 'toast:On Nov 15 it is Not yet: ready in March 2027.'], [WHEN(3), 'sheet:D40'], [PAY2, 'replace:N15'], ['Buy on Feb 1: about 2 days below $0', 'toast:On Feb 1 Everyday still goes $723 below $0, for about 2 days. That costs about $1.'], ['Buy on Feb 1 instead', 'toast:Date set to Feb 1. Everyday goes below $0 for about 2 days.'], ['Lock the safety net again', 'go:N07U']]));
